resource "open77_aetherfall"
version "0.1.0"
open77_version ">=0.0.1"
auto_start false
reload_policy "reconnect"
dependency "open77_effects >=0.2.0"
dependency "open77_locomotion_aetherfall"
dependency "open77_aetherfall_assets"
dependency "open77_aetherfall_world"
dependency "open77_aetherfall_vfx"
dependency "open77_equipment >=0.2.0"
dependency "open77_appearance >=0.2.0"
dependency "open77_wardrobe >=0.1.0"
shared_script "shared/config.lua"
-- Spell sounds: generated by scripts/aetherfall/HogwartsVfx/aetherfall_sounds.py (clips in audio/hogwarts, private).
shared_script "shared/sounds.lua"
server_script "server/duel.lua"
server_script "server/scene.lua"
server_script "server/main.lua"
client_script "client/main.lua"
web_ui_page "web/index.html"
web_ui_auto_create false
web_files { "web/**" }
files { "audio/*.wav", "audio/hogwarts/*.wav" }
permissions {
    "network.events", "input.actions", "world.effects", "world.props", "world.vehicles",
    "audio.network", "audio.play", "players.life.read", "players.life.freeze",
    "players.teleport", "combat.config", "ui.vanilla.hud", "camera.style", "perspective.policy", "locomotion.control",
    "world.npcs"
}
